  const reviewDraft=async(entry:Row)=>{if(basket.length){notify('Finish or clear the current basket before reviewing a saved draft.',true);return;}const lines=entry.envelope.payload.lines;const rebuilt=lines.map((l:Row)=>({...l,item:items.find(i=>i.id===l.itemId),notes:l.notes||'',modifierIds:l.modifierIds||[]}));if(rebuilt.some((l:Row)=>!l.item||l.modifierIds.some((id:string)=>!l.item.modifiers.some((m:Row)=>m.id===id)))){notify('A saved item or modifier is unavailable. Keep this draft and recreate the basket manually.',true);return;}setBasket(rebuilt);setService(entry.envelope.payload.service);setTable(entry.envelope.payload.tableId||'');setCustomer(entry.envelope.payload.customer||'');setNotes(entry.envelope.payload.notes||'');setDiscount(String((entry.envelope.payload.discount||0)/100));setReviewingId(entry.id);notify('Draft restored at current menu prices. Review the basket before accepting.');};
  return <>{family&&<Drawer title={`Choose ${family.name}`} onClose={()=>setFamily(null)}><p>Select the recipe and portion for this order.</p><div className="variant-choices">{[family,...family.variants].map((v:Row)=><button className="secondary variant-choice" key={v.id} disabled={!v.available||!v.stockAvailable} onClick={()=>choose(v)}><span>{v.variantLabel||'Base item'}<small>{v.available&&v.stockAvailable?v.description:'Unavailable'}</small></span><strong>{money(v.price)}</strong></button>)}</div></Drawer>}{discarding&&<Drawer title="Discard unsynced drafts?" onClose={()=>setDiscarding(false)}><p>Delete all {pending.length} saved draft(s) for {boot.outlets.find((o:Row)=>o.id===boot.outletId)?.name} in this browser? These orders have not been accepted. This cannot be undone.</p><div className="action-buttons"><button className="secondary" onClick={()=>setDiscarding(false)}>Keep drafts</button><button className="primary" disabled={busy||syncing} onClick={async()=>{await discardDrafts(boot);setPending([]);setReviewingId(null);setDiscarding(false);}}>Delete {pending.length} unsynced draft(s)</button></div></Drawer>}{pending.length>0&&<div className="sync-banner"><Clock size={18}/><span>{pending.length} local draft(s) · {pending.filter(p=>p.status==='failed').length} need review. Pending orders have no confirmed stock or payment.</span><button className="secondary" disabled={offline||busy||syncing} onClick={sync}>Sync current outlet</button><button className="text-button" disabled={busy||syncing} onClick={()=>setDiscarding(true)}>Discard drafts</button></div>}{pending.filter(p=>p.error).map(p=><div key={p.id}><ErrorBox message={`Draft ${p.id.slice(0,8)}: ${p.error}`}/><button className="secondary" disabled={offline||busy||syncing} onClick={()=>reviewDraft(p)}>Review saved draft</button></div>)}{offline&&<ErrorBox message="You are offline. You can queue a draft; payment and kitchen confirmation require a connection."/>}<p className="panel-note">{deviceReady?'This browser is prepared for signed offline drafts.':deviceChecking?'Checking offline draft readiness…':offline?'Connect to prepare this browser for offline drafts.':'Offline preparation failed. Prepare a new browser key to retry.'} {!offline&&<button className="text-button" disabled={busy||syncing} onClick={()=>run(async()=>{await rotateDevice(boot);setDeviceReady(true);return {ok:true};},'Browser prepared with a new signing key')}>Prepare new browser key</button>}</p><div className="pos-grid"><div className="pos-catalog"><div className="category-pills">{categories.map(c=><button className={category===c?'active':''} key={c} onClick={()=>setCategory(c)}>{c}</button>)}</div>{error&&<ErrorBox message={error}/>} {loading&&!items.length?<Loading/>:<div className="product-grid">{products.filter(i=>(category==='All items'||i.category===category)&&matches(i,search)).map(i=><button className={`product-tile ${!i.choiceAvailable?'sold-out':''}`} key={i.id} disabled={!i.choiceAvailable} onClick={()=>i.variants.length?setFamily(i):choose(i)}><div className={`product-accent accent-${i.station}`}><span>{i.category}</span><span>{i.prep_minutes} min</span></div><div className="product-content"><h3>{i.name}</h3><p>{i.description}</p><div><strong>{money(i.price)}</strong>{i.choiceAvailable?<Plus size={18}/>:<span className="stock-label">Unavailable</span>}</div></div></button>)}</div>}</div><section className="basket"><div className="basket-heading"><h2>Current order</h2><span>{basket.reduce((s,l)=>s+l.quantity,0)} {basket.reduce((s,l)=>s+l.quantity,0)===1?'item':'items'}</span></div><div className="basket-controls"><Field label="Service type"><select value={service} onChange={e=>setService(e.target.value)}>{['dine_in','takeaway','pickup','delivery','preorder'].map(s=><option value={s} key={s}>{label(s)}</option>)}</select></Field>{service==='dine_in'&&<Field label="Table"><select value={table} onChange={e=>setTable(e.target.value)}>{boot.tables.map((t:Row)=><option value={t.id} key={t.id}>{t.name} · {t.seats} seats</option>)}</select></Field>}</div><div className="basket-lines">{basket.length?basket.map((l,index)=><div className="basket-line" key={index}><div><strong>{l.item.name}</strong>{l.modifierIds.length>0&&<small>{l.modifierIds.map(mid=>l.item.modifiers.find((m:Row)=>m.id===mid)?.name).join(', ')}</small>}{l.notes&&<small>{l.notes}</small>}{service==='dine_in'&&<div className="basket-service-controls"><Field label={`Course · ${l.item.name} ${index+1}`}><input type="number" min="1" max="20" step="1" value={l.course||1} onChange={e=>setBasket(b=>b.map((x,i)=>i===index?{...x,course:Number(e.target.value)}:x))}/></Field><Field label={`Seat · ${l.item.name} ${index+1}`}><input type="number" min="0" max="100" step="1" value={l.seat||0} onChange={e=>setBasket(b=>b.map((x,i)=>i===index?{...x,seat:Number(e.target.value)}:x))}/></Field><label className="check-row"><input type="checkbox" checked={!!l.hold} onChange={e=>setBasket(b=>b.map((x,i)=>i===index?{...x,hold:e.target.checked}:x))}/><span>Hold course until fired</span></label></div>}<div className="qty-control"><button aria-label={`Remove one ${l.item.name}`} onClick={()=>setBasket(b=>b.flatMap((x,i)=>i!==index?[x]:x.quantity>1?[{...x,quantity:x.quantity-1}]:[]))}><Minus size={13}/></button><span>{l.quantity}</span><button aria-label={`Add one ${l.item.name}`} onClick={()=>setBasket(b=>b.map((x,i)=>i===index?{...x,quantity:x.quantity+1}:x))}><Plus size={13}/></button></div></div><div><strong>{money((l.item.price+l.modifierIds.reduce((v,mid)=>v+(l.item.modifiers.find((m:Row)=>m.id===mid)?.price||0),0))*l.quantity)}</strong><button aria-label={`Remove ${l.item.name}`} className="icon-button" onClick={()=>setBasket(b=>b.filter((_,i)=>i!==index))}><X size={15}/></button></div></div>):<Empty title="Ready for your next order" description="Choose an item from the menu."/>}</div><Field label="Customer / pickup name"><input value={customer} onChange={e=>setCustomer(e.target.value)} placeholder="Walk-in"/></Field><Field label="Kitchen notes"><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Instructions visible on the kitchen ticket" rows={2}/></Field>{boot.approvals?.discount?.some((r:Row)=>r.amount>0)&&<Field label="Approved discount · AED"><input type="number" min="0" step="0.01" max={subtotal/100} value={discount} onChange={e=>setDiscount(e.target.value)}/></Field>}<div className="basket-totals"><div><span>Net before VAT</span><span>{money(net)}</span></div><div><span>VAT · 5% included</span><span>{money(total-net)}</span></div><div className="total"><strong>Order total</strong><strong>{money(total)}</strong></div></div><button className="primary full" disabled={!basket.length||busy||disc>=subtotal} onClick={accept}>{busy?'Accepting…':offline?'Queue offline draft':'Accept & send to kitchen'}<ArrowRight size={17}/></button><p className="basket-note">VAT-inclusive prices. Payments are recorded separately.</p></section></div>{configure&&<Drawer title={`${configure.combo?'Review combo':'Customise'} ${configure.name}`} onClose={()=>setConfigure(null)}><p>{configure.description}</p><ComboContents item={configure}/>{!configure.combo&&<h3>Modifiers</h3>}{configure.modifiers.map((m:Row)=><label className="check-row" key={m.id}><input type="checkbox" checked={modifiers.includes(m.id)} onChange={e=>setModifiers(prev=>e.target.checked?[...prev,m.id]:prev.filter(x=>x!==m.id))}/><span>{m.name}</span><strong>+{money(m.price)}</strong></label>)}<Field label="Item instructions"><textarea rows={3} value={itemNotes} onChange={e=>setItemNotes(e.target.value)}/></Field><p className="panel-note">Allergens follow the chosen ingredients. Cross-contact remains subject to the kitchen's approved procedures.</p><button className="primary full" onClick={()=>add(configure,modifiers,itemNotes)}>Add to order · {money(configure.price+modifiers.reduce((s,mid)=>s+configure.modifiers.find((m:Row)=>m.id===mid).price,0))}<Plus size={17}/></button></Drawer>}</>;
