  const canWrite=r.module==='payroll'?['owner','hr'].includes(boot.user.role):r.module==='tills'?allowed(boot.user.role,'finance','till')||allowed(boot.user.role,'finance'):allowed(boot.user.role,cfg.workspace)||r.module==='purchases'&&allowed(boot.user.role,'purchasing','receive')||r.module==='batches'&&allowed(boot.user.role,'production','release');
  const submit=async(e:FormEvent)=>{e.preventDefault();const payload:Row={action,version:r.version,reason,evidence:reason};if(quantity!=='')payload[action==='closed'&&r.module==='tills'?'counted':'quantity']=Number(quantity);if(expiry)payload.expiry=expiry;if(lotCode)payload.lotCode=lotCode;const result=await run(()=>api(`/records/${r.id}/action`,payload),`${cfg.singular} ${label(action).toLowerCase()}`);if(result){setAction('');setReason('');}};
